import re

def parse_version(v):
    # 解析语义化版本号
    match = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-(.+))?$', v.strip())
    if not match:
        return None
    major, minor, patch, prerelease = match.groups()
    return (int(major), int(minor), int(patch), prerelease)

def compare_versions(v1, v2):
    p1 = parse_version(v1)
    p2 = parse_version(v2)

    # 比较主、次、修订号
    for i in range(3):
        if p1[i] != p2[i]:
            return p1[i] - p2[i]

    # 处理预发布版本
    pre1 = p1[3]
    pre2 = p2[3]

    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None:
        return 1  # 正式版本 > 预发布版本
    if pre2 is None:
        return -1

    # 都是预发布版本，按字符串比较
    if pre1 < pre2:
        return -1
    elif pre1 > pre2:
        return 1
    return 0

versions = []
with open('/data/versions.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if line:
            versions.append(line)

max_version = versions[0]
for v in versions[1:]:
    if compare_versions(v, max_version) > 0:
        max_version = v

with open('/tmp/result.txt', 'w') as f:
    f.write(max_version + '\n')

print(f"最大版本: {max_version}")
EOF
